function validate(input) {
  const [{ Employee = [], Department = [] }] = input;
  const departments = new Set(), employees = new Set(), triples = new Set();
  for (const [id] of Department) {
    if (id === null) return 'Every department needs an id.';
    if (departments.has(id)) return `Department id ${id} appears twice.`;
    departments.add(id);
  }
  for (const [id, name, salary, departmentId] of Employee) {
    if (id === null) return 'Every employee needs an id.';
    if (employees.has(id)) return `Employee id ${id} appears twice.`;
    if (salary === null) return `Employee ${id} needs a salary.`;
    if (!departments.has(departmentId)) return `Employee ${id} names department ${departmentId}, which is not in Department.`;
    const triple = JSON.stringify([String(name).toLowerCase(), salary, departmentId]);
    if (triples.has(triple)) return `Two employees share name ${name}, salary ${salary} and department ${departmentId}.`;
    employees.add(id);
    triples.add(triple);
  }
  return null;
}

