function generate(rand, size) {
  const deptNames = ['IT', 'Sales', 'HR', 'Ops', 'Legal'];
  const names = ['Joe', 'Henry', 'Sam', 'Max', 'Janet', 'Randy', 'Will', 'Ana'];
  const small = size === 'small';
  const deptCount = small ? Math.floor(rand() * 4) : 20;
  const Department = [];
  for (let id = 1; id <= deptCount; id++) Department.push([id, small ? deptNames[id - 1] : `Dept${id}`]);
  const Employee = [];
  if (deptCount > 0) {
    const count = small ? Math.floor(rand() * 9) : 2000;
    // Few salary levels in small tables give ties at every rank.
    const levels = small ? [100, 200, 300, 400, 500] : Array.from({ length: 40 }, (_, i) => 1000 * (i + 1));
    const seen = new Set();
    for (let id = 1; Employee.length < count && id <= count * 3; id++) {
      const name = small ? names[Math.floor(rand() * names.length)] : `Emp${id}`;
      const salary = levels[Math.floor(rand() * levels.length)];
      const departmentId = 1 + Math.floor(rand() * deptCount);
      const key = `${name}|${salary}|${departmentId}`;
      if (seen.has(key)) continue;
      seen.add(key);
      Employee.push([id, name, salary, departmentId]);
    }
  }
  return [{ Employee, Department }];
}
